import numpy as np
def findshift(A,B):
    H,W=A.shape
    best=None
    for p in range(-H,H+1):
        for q in range(-W,W+1):
            vals=[]
            for i in range(H):
                for j in range(W):
                    x=i+p; y=j+q
                    a = A[x][y] if 0<=x<H and 0<=y<W else None
                    if a is not None: vals.append(B[i][j]==a)
            n=sum(vals)
            if best is None or n>best[0]: best=(n,p,q)
    return best
